# So rule: for each seed, find template containing its color; candidate placements valid onto bg-or-samecolor (and maybe allowed to overwrite other seeds? but not on other templates). Among candidates rank by manhattan dist from seed to anchor cell, greedy stamping in that order, skipping if overlap with an already-placed stamp.
def solve(i_,b):
    H,W=len(i_),len(i_[0]); o=[row[:] for row in i_]
    T8=comps8(i_,b)
    multi=[c_ for c_ in T8 if len({i_[r][c] for r,c in c_})>1]
    allp=set().union(*[set(t_) for t_ in multi])
    seeds=[(r,c,i_[r][c]) for r in range(H) for c in range(W) if i_[r][c]!=b and (r,c) not in allp]
    # templates indexed by id; map seed color -> template ids containing that color
    colmap={}
    for ti,t_ in enumerate(multi):
        cols={i_[r][c] for r,c in t_}
        for v in cols: colmap.setdefault(v,[]).append(ti)
    cands=[]
    for sr,sc,sv in seeds:
        for ti in colmap.get(sv,[]):
            t_=multi[ti]
            for tr,tc,x_ in [(r,c,i_[r][c]) for r,c in t_]:
                dr=sr-tr; dc=sc-tc
                ok=True
                for r,c,x2 in t_:
                    nr,nc=r+dr,c+dc
                    if not(0<=nr<H and 0<=nc<W) or (i_[nr][nc] not in (b,x2) and (nr,nc) not in [(s[0],s[1]) for s in []]): ok=False;break
                if ok: cands.append((abs(dr)+abs(dc),ti,sr,sc,dr,dc))
    cands.sort(key=lambda x:x[0])
    occ=set()
    for d,ti,sr,sc,dr,dc in cands:
        if any(r+dr,c+dc in occ for r,c,_ in [(r,c,i_[r][c]) for r,c in multi[ti]]): continue
        for r,c,x2 in multi[ti]: occ.add((r+dr,c+dc)); o[r+dr][c+dc]=x2
    return o
for k,bg in [('Demo pair 1',4),('Demo pair 2',1),('Demo pair 3',6),('Demo pair 4',5),('Demo pair 5',5),('Demo pair 6',0),('Demo pair 7',0),('Demo pair 8',5)]:
    got=solve(G[k+' input'],bg)
    print(k,'match',got==G[k+' output'])

import os,re
from collections import Counter as Ct
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps8(g,bg):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=bg and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    p=q.pop(); cells.append(p)
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=p[0]+dr,p[1]+dc
                            if 0<=nr<len(g) and 0<=nc<len(g[0]) and g[nr][nc]!=bg and (nr,nc) not in seen:
                                seen.add((nr,nc)); q.append((nr,nc))
                out.append(cells)
    return out
def solve(i_,b):
    H,W=len(i_),len(i_[0]); o=[row[:] for row in i_]
    multi=[c_ for c_ in comps8(i_,b) if len({i_[r][c] for r,c in c_})>1]
    allp=set().union(*multi)
    seeds=[(r,c,i_[r][c]) for r in range(H) for c in range(W) if i_[r][c]!=b and (r,c) not in allp]
    colmap={}
    for ti,t_ in enumerate(multi):
        cols={i_[r][c] for r,c in t_}
        for v in cols: colmap.setdefault(v,[]).append(ti)
    cands=[]
    for sr,sc,sv in seeds:
        for ti in colmap.get(sv,[]):
            t_=multi[ti]
            for tr,tc,x_ in [(r,c,i_[r][c]) for r,c in t_]:
                dr=sr-tr; dc=sc-tc
                ok=True
                for r,c,x2 in t_:
                    nr,nc=r+dr,c+dc
                    if not(0<=nr<H and 0<=nc<W) or (i_[nr][nc] not in (b,x2)): ok=False;break
                if ok: cands.append((abs(dr)+abs(dc),ti,sr,sc,dr,dc))
    cands.sort(key=lambda x:(x[0],x[1]))
    occ=set()
    for _,ti,sr,sc,dr,dc in cands:
        hit=[(r+dr,c+dc) for r,c,_ in multi[ti]]
        if any(p in occ for p in hit): continue
        occ.update(hit)
        for r,c,x2 in multi[ti]: o[r+dr][c+dc]=x2
    return o
for k,bg in [('Demo pair 1',4),('Demo pair 2',1),('Demo pair 3',6),('Demo pair 4',5),('Demo pair 5',5),('Demo pair 6',0),('Demo pair 7',0),('Demo pair 8',5)]:
    got=solve(G[k+' input'],bg)
    print(k,'match',got==G[k+' output'])

